from html.parser import HTMLParser
class P(HTMLParser):
    def __init__(self):
        super().__init__(); self.stack=[]; self.void={'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}
    def handle_starttag(self, tag, attrs):
        if tag not in self.void: self.stack.append(tag)
    def handle_endtag(self, tag):
        if tag in self.void: return
        if self.stack and self.stack[-1]==tag: self.stack.pop()
        else: print('MISMATCH close', tag, 'stack tail', self.stack[-5:])
p=P(); p.feed(open('index.html').read()); print('unclosed:', p.stack)
EOF
