from playwright.sync_api import sync_playwright
import pathlib, json
url = pathlib.Path('index.html').resolve().as_uri()
with sync_playwright() as p:
    b = p.chromium.launch(executable_path='/usr/bin/google-chrome', args=['--no-sandbox'])
    for w,h in [(320,700),(375,812),(768,1024),(1024,900),(1440,1000)]:
        pg = b.new_page(viewport={'width':w,'height':h})
        pg.goto(url, wait_until='networkidle'); pg.wait_for_timeout(600)
        pg.evaluate("window.scrollTo(0, document.body.scrollHeight)"); pg.wait_for_timeout(900)
        res = pg.evaluate("""() => {
          const over=[...document.querySelectorAll('body *')].filter(el=>{
            const r=el.getBoundingClientRect(); const cs=getComputedStyle(el);
            if(cs.position==='fixed'||cs.display==='none'||cs.visibility==='hidden') return false;
            return r.right>document.documentElement.clientWidth+1 || r.left<-1;
          }).slice(0,12).map(el=>({t:el.tagName,c:el.className, r:Math.round(el.getBoundingClientRect().right), l:Math.round(el.getBoundingClientRect().left)}));
          const clip=[...document.querySelectorAll('.btn,.nav a,.status,.c-link,.project,.skill-list li,.pending,.tag,.feature-foot,.hero-gh')].filter(el=>el.scrollWidth>el.clientWidth+1).map(el=>({c:el.className,w:el.clientWidth,sw:el.scrollWidth}));
          return {over, clip, fonts: {quick:document.fonts.check('700 100px Quicksand'), caveat:document.fonts.check('600 24px Caveat'), loaded:[...document.fonts].filter(f=>f.status==='loaded').map(f=>f.family+' '+f.weight).slice(0,10)}};
        }""")
        print(w, json.dumps(res, ensure_ascii=False))
        pg.close()
    b.close()
EOF

