        res = pg.evaluate("""() => {
          const h=document.querySelector('.hero-name');
          const r=document.createRange(); r.selectNodeContents(h);
          const tr=r.getBoundingClientRect();
          const head=document.querySelector('.head-inner');
          const kids=[...head.children].map(c=>({c:c.className, l:Math.round(c.getBoundingClientRect().left), r:Math.round(c.getBoundingClientRect().right)}));
          const overlap = kids.some((a,i)=>i&&a.l<kids[i-1].r-1);
          const status=document.querySelector('.status').getBoundingClientRect();
          const btn=document.querySelector('.ticker-toggle').getBoundingClientRect();
          const c=document.querySelector('.c-link');
          return {textRight:Math.round(tr.right), textLeft:Math.round(tr.left), heroRight:Math.round(h.getBoundingClientRect().right), vw:innerWidth, headOverlap:overlap, kids, status:[Math.round(status.width),Math.round(status.height)], tickerBtn:[Math.round(btn.width),Math.round(btn.height)], cLinkOverflow:c.scrollWidth>c.clientWidth, pendingVisible:getComputedStyle(document.querySelector('.c-link .pending')).display};
        }""")
        print(w, json.dumps(res, ensure_ascii=False))
        pg.close()
    b.close()
EOF

